// Package argparse is a small command-line argument parser supporting boolean
// flags, flags with values, positional arguments and generated help.
//
// Accepted syntax:
//
//	--name value   --name=value   -n value   -n=value   -nvalue
//	--verbose      --verbose=false           -v         -vq (grouped booleans)
//	--             everything after it is positional
//	-h, --help     Parse returns ErrHelp
package argparse

import (
	"errors"
	"fmt"
	"io"
	"strconv"
	"strings"
	"text/tabwriter"
	"unicode/utf8"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flag struct {
	long  string
	short rune   // 0 if the flag has no short form
	help  string
	kind  string // value placeholder shown in help; "" for booleans
	def   string // default shown in help; "" to omit
	set   func(string) error
}

type positional struct {
	name, help string
	dest       *string
}

// Parser holds the flag and argument definitions for one command.
type Parser struct {
	name, desc string
	flags      []*flag
	args       []positional
	rest       *positional // nil unless Rest was called
	restDest   *[]string
}

// New returns a parser for the program name, with a one-line description
// shown in the help message.
func New(name, desc string) *Parser {
	return &Parser{name: name, desc: desc}
}

// Bool defines a boolean flag. Pass 0 as short for a long-only flag.
func (p *Parser) Bool(long string, short rune, help string) *bool {
	v := new(bool)
	p.add(&flag{long: long, short: short, help: help, set: func(s string) error {
		b, err := strconv.ParseBool(s)
		if err != nil {
			return errors.New("expected true or false")
		}
		*v = b
		return nil
	}})
	return v
}

// String defines a flag taking a string value.
func (p *Parser) String(long string, short rune, def, help string) *string {
	v := new(string)
	*v = def
	f := &flag{long: long, short: short, help: help, kind: "string", set: func(s string) error {
		*v = s
		return nil
	}}
	if def != "" {
		f.def = strconv.Quote(def)
	}
	p.add(f)
	return v
}

// Int defines a flag taking an integer value.
func (p *Parser) Int(long string, short rune, def int, help string) *int {
	v := new(int)
	*v = def
	p.add(&flag{long: long, short: short, help: help, kind: "int", def: strconv.Itoa(def), set: func(s string) error {
		n, err := strconv.Atoi(s)
		if err != nil {
			return errors.New("expected an integer")
		}
		*v = n
		return nil
	}})
	return v
}

// Arg defines a required positional argument. Positionals are filled in the
// order they are defined.
func (p *Parser) Arg(name, help string) *string {
	v := new(string)
	p.args = append(p.args, positional{name, help, v})
	return v
}

// Rest collects any positional arguments left over after those defined with
// Arg. Without it, extra positional arguments are an error.
func (p *Parser) Rest(name, help string) *[]string {
	if p.rest != nil {
		panic("argparse: Rest defined twice")
	}
	p.rest = &positional{name: name, help: help}
	p.restDest = new([]string)
	return p.restDest
}

func (p *Parser) add(f *flag) {
	if f.long == "" || strings.HasPrefix(f.long, "-") || strings.ContainsAny(f.long, "= ") {
		panic(fmt.Sprintf("argparse: invalid flag name %q", f.long))
	}
	if f.long == "help" || p.byLong(f.long) != nil {
		panic(fmt.Sprintf("argparse: flag --%s already defined", f.long))
	}
	if f.short != 0 && p.byShort(f.short) != nil {
		panic(fmt.Sprintf("argparse: flag -%c already defined", f.short))
	}
	p.flags = append(p.flags, f)
}

func (p *Parser) byLong(name string) *flag {
	for _, f := range p.flags {
		if f.long == name {
			return f
		}
	}
	return nil
}

func (p *Parser) byShort(r rune) *flag {
	for _, f := range p.flags {
		if f.short == r {
			return f
		}
	}
	return nil
}

// Parse parses args, which should not include the program name
// (typically os.Args[1:]).
func (p *Parser) Parse(args []string) error {
	var pos []string
	for i := 0; i < len(args); i++ {
		a := args[i]
		switch {
		case a == "--":
			pos = append(pos, args[i+1:]...)
			i = len(args)

		case strings.HasPrefix(a, "--"):
			name, val, hasVal := strings.Cut(a[2:], "=")
			if name == "help" {
				return ErrHelp
			}
			f := p.byLong(name)
			if f == nil {
				return fmt.Errorf("unknown flag --%s", name)
			}
			if !hasVal {
				if f.kind == "" {
					val = "true"
				} else if i++; i < len(args) {
					val = args[i]
				} else {
					return fmt.Errorf("flag --%s needs a value", name)
				}
			}
			if err := f.set(val); err != nil {
				return fmt.Errorf("invalid value %q for flag --%s: %v", val, name, err)
			}

		case len(a) > 1 && a[0] == '-':
			// One or more short flags. A flag that takes a value consumes
			// the remainder of the group, or the next argument if none.
			group := a[1:]
			for group != "" {
				r, size := utf8.DecodeRuneInString(group)
				group = group[size:]
				f := p.byShort(r)
				if f == nil {
					if r == 'h' {
						return ErrHelp
					}
					return fmt.Errorf("unknown flag -%c", r)
				}
				val := "true"
				if f.kind != "" {
					if group != "" {
						val = strings.TrimPrefix(group, "=")
						group = ""
					} else if i++; i < len(args) {
						val = args[i]
					} else {
						return fmt.Errorf("flag -%c needs a value", r)
					}
				}
				if err := f.set(val); err != nil {
					return fmt.Errorf("invalid value %q for flag -%c: %v", val, r, err)
				}
			}

		default: // includes a lone "-", conventionally stdin
			pos = append(pos, a)
		}
	}

	if len(pos) < len(p.args) {
		return fmt.Errorf("missing argument <%s>", p.args[len(pos)].name)
	}
	for i, arg := range p.args {
		*arg.dest = pos[i]
	}
	extra := pos[len(p.args):]
	if p.rest == nil {
		if len(extra) > 0 {
			return fmt.Errorf("unexpected argument %q", extra[0])
		}
		return nil
	}
	*p.restDest = extra
	return nil
}

// Usage writes a help message generated from the definitions to w.
func (p *Parser) Usage(w io.Writer) {
	fmt.Fprintf(w, "Usage: %s [options]", p.name)
	for _, a := range p.args {
		fmt.Fprintf(w, " <%s>", a.name)
	}
	if p.rest != nil {
		fmt.Fprintf(w, " [%s...]", p.rest.name)
	}
	fmt.Fprintln(w)
	if p.desc != "" {
		fmt.Fprintf(w, "\n%s\n", p.desc)
	}

	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	if len(p.args) > 0 || p.rest != nil {
		fmt.Fprintln(tw, "\nArguments:")
		for _, a := range p.args {
			fmt.Fprintf(tw, "  %s\t%s\n", a.name, a.help)
		}
		if p.rest != nil {
			fmt.Fprintf(tw, "  %s...\t%s\n", p.rest.name, p.rest.help)
		}
		tw.Flush() // align arguments and options independently
	}

	fmt.Fprintln(tw, "\nOptions:")
	for _, f := range p.flags {
		left := "    "
		if f.short != 0 {
			left = fmt.Sprintf("-%c, ", f.short)
		}
		left += "--" + f.long
		if f.kind != "" {
			left += " <" + f.kind + ">"
		}
		help := f.help
		if f.def != "" {
			help += " (default " + f.def + ")"
		}
		fmt.Fprintf(tw, "  %s\t%s\n", left, help)
	}
	if p.byShort('h') == nil {
		fmt.Fprintln(tw, "  -h, --help\tshow this help")
	} else {
		fmt.Fprintln(tw, "      --help\tshow this help")
	}
	tw.Flush()
}

package argparse

import (
	"errors"
	"reflect"
	"strings"
	"testing"
)

type result struct {
	verbose, quiet bool
	name           string
	count          int
	file           string
	extra          []string
}

func parse(args ...string) (result, error) {
	p := New("greet", "Greet people.")
	verbose := p.Bool("verbose", 'v', "verbose output")
	quiet := p.Bool("quiet", 'q', "no output")
	name := p.String("name", 'n', "world", "who to greet")
	count := p.Int("count", 'c', 1, "repetitions")
	file := p.Arg("file", "input file")
	extra := p.Rest("extra", "more files")
	err := p.Parse(args)
	return result{*verbose, *quiet, *name, *count, *file, *extra}, err
}

func TestParse(t *testing.T) {
	tests := []struct {
		args []string
		want result
	}{
		{[]string{"f"}, result{name: "world", count: 1, file: "f"}},
		{[]string{"--verbose", "--name", "bob", "--count=3", "f"}, result{verbose: true, name: "bob", count: 3, file: "f"}},
		{[]string{"-v", "-n", "bob", "-c=3", "f"}, result{verbose: true, name: "bob", count: 3, file: "f"}},
		{[]string{"-vqnbob", "-c3", "f"}, result{verbose: true, quiet: true, name: "bob", count: 3, file: "f"}},
		{[]string{"-vc", "-5", "f"}, result{verbose: true, name: "world", count: -5, file: "f"}},
		{[]string{"-v", "--verbose=false", "--name=", "f"}, result{count: 1, file: "f"}},
		{[]string{"f", "-v", "a", "b"}, result{verbose: true, name: "world", count: 1, file: "f", extra: []string{"a", "b"}}},
		{[]string{"-", "--", "-v", "--name"}, result{name: "world", count: 1, file: "-", extra: []string{"-v", "--name"}}},
	}
	for _, tt := range tests {
		got, err := parse(tt.args...)
		if err != nil {
			t.Errorf("%q: unexpected error: %v", tt.args, err)
			continue
		}
		if len(got.extra) == 0 {
			got.extra = nil
		}
		if !reflect.DeepEqual(got, tt.want) {
			t.Errorf("%q:\n got %+v\nwant %+v", tt.args, got, tt.want)
		}
	}
}

func TestParseErrors(t *testing.T) {
	tests := []struct {
		args []string
		want string
	}{
		{[]string{}, "missing argument <file>"},
		{[]string{"--nope", "f"}, "unknown flag --nope"},
		{[]string{"-vx", "f"}, "unknown flag -x"},
		{[]string{"f", "--name"}, "flag --name needs a value"},
		{[]string{"f", "-vn"}, "flag -n needs a value"},
		{[]string{"--count", "abc", "f"}, `invalid value "abc" for flag --count: expected an integer`},
		{[]string{"--verbose=maybe", "f"}, `invalid value "maybe" for flag --verbose: expected true or false`},
	}
	for _, tt := range tests {
		_, err := parse(tt.args...)
		if err == nil || err.Error() != tt.want {
			t.Errorf("%q: got error %v, want %q", tt.args, err, tt.want)
		}
	}
}

func TestHelp(t *testing.T) {
	for _, arg := range []string{"-h", "--help", "-vh"} {
		if _, err := parse(arg); !errors.Is(err, ErrHelp) {
			t.Errorf("%s: got %v, want ErrHelp", arg, err)
		}
	}
}

func TestUnexpectedArgument(t *testing.T) {
	p := New("x", "")
	p.Arg("file", "input file")
	err := p.Parse([]string{"a", "b"})
	if err == nil || err.Error() != `unexpected argument "b"` {
		t.Errorf("got %v", err)
	}
}

func TestUsage(t *testing.T) {
	p := New("greet", "Greet people.")
	p.Bool("verbose", 'v', "verbose output")
	p.String("name", 'n', "world", "who to greet")
	p.Int("count", 0, 1, "repetitions")
	p.Arg("file", "input file")
	p.Rest("extra", "more files")

	var b strings.Builder
	p.Usage(&b)
	want := `Usage: greet [options] <file> [extra...]

Greet people.

Arguments:
  file      input file
  extra...  more files

Options:
  -v, --verbose        verbose output
  -n, --name <string>  who to greet (default "world")
      --count <int>    repetitions (default 1)
  -h, --help           show this help
`
	if b.String() != want {
		t.Errorf("got:\n%s\nwant:\n%s", b.String(), want)
	}
}

package main

import (
	"errors"
	"fmt"
	"os"

	"argparse"
)

func main() {
	p := argparse.New("greet", "Print a greeting for each line of a file.")
	verbose := p.Bool("verbose", 'v', "print extra detail")
	name := p.String("name", 'n', "world", "who to greet")
	count := p.Int("count", 'c', 1, "number of greetings")
	file := p.Arg("file", "input file")
	extra := p.Rest("extra", "additional input files")

	if err := p.Parse(os.Args[1:]); errors.Is(err, argparse.ErrHelp) {
		p.Usage(os.Stdout)
		return
	} else if err != nil {
		fmt.Fprintf(os.Stderr, "greet: %v\n\n", err)
		p.Usage(os.Stderr)
		os.Exit(2)
	}

	for i := 0; i < *count; i++ {
		fmt.Printf("Hello, %s!\n", *name)
	}
	if *verbose {
		fmt.Printf("file=%q extra=%q\n", *file, *extra)
	}
}

