		os.Exit(2)
	}

	for i := 0; i < *count; i++ {
		fmt.Printf("Hello, %s!\n", *name)
	}
	if *verbose {
		fmt.Printf("file=%q extra=%q\n", *file, *extra)
	}
}
```

`go run ./example -h` should print:

```
Usage: greet [options] <file> [extra...]

Print a greeting for each line of a file.

Arguments:
  file      input file
  extra...  additional input files

Options:
  -v, --verbose        print extra detail
  -n, --name <string>  who to greet (default "world")
  -c, --count <int>    number of greetings (default 1)
  -h, --help           show this help
```

Behaviour you might not expect:

- **Flag order:** flags and positionals can be interleaved (`greet file -v` works); `--` ends flag parsing.
- **Value flags take the next argument unconditionally:** `--count -5` works, but `--name --verbose` sets the name to `"--verbose"`.
- **Negative numbers as positionals:** a bare `-5` is read as a flag, so it needs `--` before it.
- **Help:** `Parse` returns `ErrHelp` rather than printing and exiting, so the caller decides where usage goes and what the exit code is.
- **Positionals:** `Arg` is always required and `Rest` takes zero or more; there is no optional single positional.
- **Definition mistakes:** a duplicate flag name, or defining `--help` yourself, panics at definition time.
